    var dumbbellData = [{"country": "Ethiopia", "rural": 340, "urban": 160}, {"country": "India", "rural": 128, "urban": 62}, {"country": "Rwanda", "rural": 260, "urban": 125}, {"country": "Bangladesh", "rural": 158, "urban": 75}, {"country": "Nigeria", "rural": 860, "urban": 350}, {"country": "Cambodia", "rural": 285, "urban": 120}, {"country": "Peru", "rural": 125, "urban": 38}, {"country": "Nepal", "rural": 215, "urban": 85}];
    var midwifeData = [{"country": "Ethiopia", "coverage": 50, "mmr": 267}, {"country": "India", "coverage": 81, "mmr": 97}, {"country": "Rwanda", "coverage": 91, "mmr": 203}, {"country": "Bangladesh", "coverage": 59, "mmr": 123}, {"country": "Nigeria", "coverage": 43, "mmr": 621}, {"country": "Cambodia", "coverage": 89, "mmr": 218}, {"country": "Peru", "coverage": 95, "mmr": 69}, {"country": "Nepal", "coverage": 77, "mmr": 151}];
