custom_scripts = data_js + """
    var chartsBuilt = false;

    function resetCanvas(id) {
      var old = document.getElementById(id);
      if (!old) return null;
      var parent = old.parentNode;
      var canvas = document.createElement('canvas');
      canvas.id = id;
      canvas.setAttribute('role', 'img');
      canvas.setAttribute('aria-label', old.getAttribute('aria-label'));
      parent.replaceChild(canvas, old);
      return canvas;
    }

    function buildCharts() {
      if (chartsBuilt || typeof Chart === 'undefined') return;
      Chart.defaults.animation = false;

      var isDark = document.documentElement.classList.contains('theme-dark');
      var colors = {
        text: isDark ? '#EDEDED' : '#0f172a',
        textSec: isDark ? '#888' : '#64748b',
        border: isDark ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)',
        grid: isDark ? 'rgba(255,255,255,0.04)' : 'rgba(0,0,0,0.04)',
        rural: isDark ? '#f43f5e' : '#e11d48',
        urban: isDark ? '#3b82f6' : '#2563eb',
        palette: ['#3b82f6', '#f43f5e', '#10b981', '#f59e0b', '#8b5cf6', '#06b6d4', '#ec4899', '#84cc16']
      };

      // 1. Connected Scatter Plot (Expenditure vs MMR)
      var scatterCtx = resetCanvas('scatterChart');
      if (scatterCtx) {
        var scatterDatasets = [];
        var cIdx = 0;
        for (var country in scatterData) {
          var pts = scatterData[country];
          var color = colors.palette[cIdx % colors.palette.length];
          // Make the last point larger to indicate direction
          var pointRadii = pts.map(function(p, i) { return i === pts.length - 1 ? 8 : 4; });
          var pointStyles = pts.map(function(p, i) { return i === pts.length - 1 ? 'triangle' : 'circle'; });

          scatterDatasets.push({
            label: country,
            data: pts,
            borderColor: color,
            backgroundColor: color,
            pointRadius: pointRadii,
            pointHoverRadius: 10,
            pointStyle: pointStyles,
            showLine: true,
            borderWidth: 2,
            fill: false,
            tension: 0.1
          });
          cIdx++;
        }

        new Chart(scatterCtx, {
          type: 'scatter',
          data: { datasets: scatterDatasets },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              tooltip: { enabled: true, cornerRadius: 8, padding: 12 },
              legend: { position: 'right', labels: { color: colors.text, usePointStyle: true, boxWidth: 10 } }
            },
            scales: {
              x: {
                title: { display: true, text: 'Health Expenditure (% of GDP)', color: colors.textSec },
                ticks: { color: colors.textSec },
                grid: { color: colors.grid }
              },
              y: {
                title: { display: true, text: 'Maternal Mortality Ratio', color: colors.textSec },
                ticks: { color: colors.textSec },
                grid: { color: colors.grid }
              }
            }
          }
        });
      }

      // 2. Dumbbell Chart (Rural vs Urban)
      // Using floating bar for the connecting line, and scatter for the endpoints
      var dumbbellCtx = resetCanvas('dumbbellChart');
      if (dumbbellCtx) {
        var labels = dumbbellData.map(function(d) { return d.country; });
        var linesData = dumbbellData.map(function(d) { return [d.urban, d.rural]; });
        var urbanData = dumbbellData.map(function(d) { return {x: d.urban, y: d.country}; });
        var ruralData = dumbbellData.map(function(d) { return {x: d.rural, y: d.country}; });

        new Chart(dumbbellCtx, {
          type: 'bar',
          data: {
            labels: labels,
            datasets: [
              {
                type: 'bar',
                label: 'Gap',
                data: linesData,
                backgroundColor: colors.border,
                barThickness: 4,
                borderRadius: 2
              },
              {
                type: 'scatter',
                label: 'Urban',
                data: urbanData,
                backgroundColor: colors.urban,
                pointRadius: 6,
                pointHoverRadius: 8
              },
              {
                type: 'scatter',
                label: 'Rural',
                data: ruralData,
                backgroundColor: colors.rural,
                pointRadius: 6,
                pointHoverRadius: 8
              }
            ]
          },
          options: {
            indexAxis: 'y',
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              tooltip: { enabled: true },
              legend: { position: 'top', labels: { color: colors.text, usePointStyle: true } }
            },
            scales: {
              x: {
                title: { display: true, text: 'Maternal Mortality Ratio', color: colors.textSec },
                ticks: { color: colors.textSec },
                grid: { color: colors.grid }
              },
              y: {
                ticks: { color: colors.textSec },
                grid: { display: false }
              }
            }
          }
        });
      }

      // 3. Midwife Coverage vs MMR Scatter
      var midwifeCtx = resetCanvas('midwifeChart');
      if (midwifeCtx) {
        var midwifeDatasets = [];
        var mIdx = 0;
        midwifeData.forEach(function(d) {
          midwifeDatasets.push({
            label: d.country,
            data: [{x: d.coverage, y: d.mmr}],
            backgroundColor: colors.palette[mIdx % colors.palette.length],
            pointRadius: 10,
            pointHoverRadius: 12
          });
          mIdx++;
        });

        new Chart(midwifeCtx, {
          type: 'scatter',
          data: { datasets: midwifeDatasets },
          options: {
            responsive: true,
            maintainAspectRatio: false,
            plugins: {
              tooltip: {
                enabled: true,
                callbacks: {
                  label: function(ctx) { return ctx.dataset.label + ': ' + ctx.parsed.x + '% coverage, ' + ctx.parsed.y + ' MMR'; }
                }
              },
              legend: { display: false } // Hide legend as we have too many
            },
            scales: {
              x: {
                title: { display: true, text: 'Skilled Birth Attendant Coverage (%)', color: colors.textSec },
                ticks: { color: colors.textSec },
                grid: { color: colors.grid }
              },
              y: {
                title: { display: true, text: 'Maternal Mortality Ratio (2021)', color: colors.textSec },
                ticks: { color: colors.textSec },
                grid: { color: colors.grid }
              }
            }
          }
        });
      }

      chartsBuilt = true;
    }

    function onThemeChange() {
      chartsBuilt = false;
      setTimeout(buildCharts, 50);
    }

    // Add Chart.js script if not present
    var script = document.createElement('script');
    script.src = '/app/libs/chart.js';
    script.onload = buildCharts;
    document.head.appendChild(script);
"""

html_content = html_content.replace('<!-- ADD YOUR STYLES BELOW -->', custom_styles)
html_content = html_content.replace('<!-- YOUR CONTENT HERE (use <section>, <header>, <article> for semantics) -->', content_html)
