# Remove the Chart.js CDN comment to avoid confusion, since we dynamically inject it or we can just replace it in the head.
html_content = html_content.replace('<!-- ADD CDN LIBRARIES HERE (Chart.js, Mermaid, etc.) -->', '<script src="/app/libs/chart.js"></script>')

# Since we injected Chart.js in head, we don't need dynamic load in custom_scripts, but we can leave it or remove it.
# Actually, let's fix it by relying on the <head> tag and DOMContentLoaded
custom_scripts_fixed = custom_scripts.replace("var script = document.createElement('script');\n    script.src = '/app/libs/chart.js';\n    script.onload = buildCharts;\n    document.head.appendChild(script);", "document.addEventListener('DOMContentLoaded', buildCharts);")

html_content = html_content.replace(custom_scripts, custom_scripts_fixed)

with open('/app/dashboard.html', 'w') as f:
    f.write(html_content)

print("Dashboard HTML created at /app/dashboard.html")
